function drawBoard(){const board=$('#board');board.innerHTML='';tiles.forEach((t,i)=>{const [r,c]=coords(i);const e=document.createElement('div');e.className=`tile ${t.type} ${g.players.some(p=>p.pos===i)?'current-tile':''}`;e.style.gridRow=r;e.style.gridColumn=c;e.innerHTML=`<span class="tile-icon">${t.icon}</span><div><div class="tile-name">${t.name}</div><div class="tile-type">${t.kind}</div></div><span class="tile-meta">${t.detail}</span>`;let owner=g.players.find(p=>p.owned.includes(i));if(owner){const o=document.createElement('i');o.className='tile-owner';o.style.background=owner.color;e.append(o)}const pawns=document.createElement('div');pawns.className='tile-pawns';g.players.filter(p=>p.pos===i).forEach(p=>{const pawn=document.createElement('i');pawn.className='pawn';pawn.style.setProperty('--pawn',p.color);pawn.title=p.name;pawns.append(pawn)});e.append(pawns);board.append(e)});const center=document.createElement('div');center.className='cell-center';center.innerHTML=`<div class="australia-mark">✳</div><div class="center-kicker">AUSTRALIA / 2026</div><div class="center-title">The long game.</div><div class="center-copy">Trade, resilience &amp; a changing world</div><div class="center-quarter">QUARTER ${String(g.round).padStart(2,'0')} &nbsp;·&nbsp; ${g.weather}</div>`;board.append(center)}
