function sfx(type){if(!audioOn)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),v=audioCtx.createGain();o.connect(v);v.connect(audioCtx.destination);o.type='triangle';o.frequency.value=type==='dice'?260:type==='cash'?560:380;v.gain.setValueAtTime(.055,audioCtx.currentTime);v.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.17);o.start();o.stop(audioCtx.currentTime+.18)}catch{}}
