function openTrade(){const p=g.players[g.turn];if(p.tradeUsed){toast('Your market action is already used this quarter.');return}const rows=goods.map(x=>{const have=p.inventory[x]||0,price=g.market[x]||10;return `<div class="trade-row"><div><b>${x}</b><small>Holding ${have} unit${have===1?'':'s'} · market A$${price}m</small></div><span class="trade-value">A$${price}m</span><div class="trade-actions"><button class="mini-btn" data-action="buy" data-good="${x}" ${p.cash<price?'disabled':''}>BUY</button><button class="mini-btn" data-action="sell" data-good="${x}" ${have<1?'disabled':''}>SELL</button></div></div>`}).join('');modal('Trade the market','ONE MARKET ACTION / PER QUARTER',`<p class="modal-copy">Buy a strategic reserve or take advantage of a price spike. Your action is used on your first trade.</p><div class="trade-list">${rows}</div><div class="modal-foot"><span>AVAILABLE FUNDS</span><b>A$${Math.round(p.cash)}m</b></div>`);$$('.mini-btn',$('#modal-root')).forEach(b=>b.onclick=()=>trade(b.dataset.action,b.dataset.good))}
function trade(action,good){const p=g.players[g.turn],price=g.market[good];if(action==='buy'){if(p.cash<price)return;p.cash-=price;p.inventory[good]=(p.inventory[good]||0)+1;addLog(p.name.toUpperCase(),`Bought ${good} for A$${price}m.`)}else{if(!(p.inventory[good]>0))return;p.inventory[good]--;p.cash+=price;addLog(p.name.toUpperCase(),`Sold ${good} for A$${price}m.`)}p.tradeUsed=true;sfx('cash');render();$('#modal-root').classList.add('hidden');toast(`${action==='buy'?'Bought':'Sold'} ${good} · A$${price}m`)}
function openPolicy(){const p=g.players[g.turn];if(p.policyUsed){toast('Policy is locked in for this quarter.');return}const arr=[['balanced','Balanced','Keep the budget steady. No major advantage or downside.','No cost'],['local-first','Local first','Back domestic production. Stronger resilience and protection from import shocks.','A$8m investment'],['open-trade','Open trade','Cut tariffs and lean into global markets. Exports pay more; imports cost less.','A$4m revenue']];modal('Set national policy','ONE POLICY DECISION / PER QUARTER',`<p class="modal-copy">Policy shapes your trade strategy for this quarter. Choose carefully — you can change it next quarter.</p><div class="policy-grid">${arr.map(([id,n,d,c])=>`<button class="policy-choice ${p.policy===id?'active':''}" data-policy="${id}"><b>${n}</b><small>${d}</small><span>${c}</span></button>`).join('')}</div>`);$$('.policy-choice',$('#modal-root')).forEach(b=>b.onclick=()=>setPolicy(b.dataset.policy))}
function setPolicy(id){const p=g.players[g.turn],cost=id==='local-first'?8:id==='open-trade'?-4:0;if(p.cash<Math.max(cost,0)){toast('Not enough funds for this policy.');return}p.cash-=cost;p.policy=id;p.policyUsed=true;addLog(p.name.toUpperCase(),`Set ${id.replace('-',' ')} policy.`);$('#modal-root').classList.add('hidden');render();sfx('cash');toast('Policy adopted for this quarter.')}

