function roll(){if(g.done)return;const p=g.players[g.turn];if(!p.human)return;const btn=$('#roll-btn');btn.disabled=true;btn.classList.add('rolling');sfx('dice');let count=0;const anim=setInterval(()=>{$('#die-one').textContent=['⚀','⚁','⚂','⚃','⚄','⚅'][Math.random()*6|0];$('#die-two').textContent=['⚀','⚁','⚂','⚃','⚄','⚅'][Math.random()*6|0];if(++count>7){clearInterval(anim);const a=1+(Math.random()*6|0),b=1+(Math.random()*6|0);g.lastRoll=[a,b];$('#die-one').textContent=['⚀','⚁','⚂','⚃','⚄','⚅'][a-1];$('#die-two').textContent=['⚀','⚁','⚂','⚃','⚄','⚅'][b-1];btn.classList.remove('rolling');moveCurrent(a+b)}},90)}
function moveCurrent(steps){const p=g.players[g.turn],old=p.pos;p.pos=(p.pos+steps)%tiles.length;if(old+steps>=tiles.length){p.cash+=15;addLog(p.name.toUpperCase(),'Passed Canberra — A$15m federal transfer received.')}$('#board').classList.add('board-move');setTimeout(()=>$('#board').classList.remove('board-move'),500);render();const t=tiles[p.pos];addLog(p.name.toUpperCase(),`Rolled ${g.lastRoll[0]} + ${g.lastRoll[1]} and landed at ${t.name}.`);sfx('cash');resolveTile(p,t)}
function resolveTile(p,t){const policy=p.policy;let amount=t.price||0;if(policy==='open-trade'&&t.type==='export')amount+=3;if(policy==='open-trade'&&t.type==='import')amount=Math.max(2,amount-3);if(policy==='local-first'&&t.type==='import')amount=Math.max(2,amount-2);
if(t.type==='export'){let owner=g.players.find(x=>x.owned.includes(p.pos));if(owner&&owner!==p){const rent=Math.max(3,Math.round(amount*.45));p.cash-=rent;owner.cash+=rent;addLog(owner.name.toUpperCase(),`${t.name} asset paid A$${rent}m lease.`);finishLanding(`${t.name} is held by ${owner.name}. You paid A$${rent}m in access fees.`);return}p.cash+=amount;const good=t.resource;p.inventory[good]=(p.inventory[good]||0)+1;let ownerText=p.owned.includes(p.pos)?' Asset dividend included.':' Export receipts and one reserve unit added.';finishLanding(`${t.name} earns A$${amount}m.${ownerText}`,{buy:!owner&&!p.owned.includes(p.pos),price:24});return}
if(t.type==='import'){let owner=g.players.find(x=>x.owned.includes(p.pos));if(owner&&owner!==p){const rent=Math.max(3,Math.round(amount*.4));p.cash-=rent;owner.cash+=rent;finishLanding(`${t.name} gateway belongs to ${owner.name}. Access fee: A$${rent}m.`);return}if(policy==='local-first')amount=Math.max(2,amount-2);p.cash-=amount;if((p.inventory[t.resource]||0)>0){p.inventory[t.resource]--;p.cash+=Math.ceil(amount*.45);finishLanding(`${t.name}: A$${amount}m import bill. A reserve unit offset part of the cost.`)}else finishLanding(`${t.name}: A$${amount}m import bill. No strategic reserve was available.`,{buy:!owner&&!p.owned.includes(p.pos),price:24});return}
if(t.type==='event'){const card=cards[Math.random()*cards.length|0];card.run(g);g.events++;render();finishEvent(card);return}
let income=t.effect==='capital'?5:t.effect==='port'?8:6;const owner=g.players.find(x=>x.owned.includes(p.pos));if(owner&&owner!==p){const rent=income;owner.cash+=rent;p.cash-=rent;finishLanding(`${t.name} is operated by ${owner.name}. A$${rent}m service fee transferred.`);return}if(t.effect==='port'&&policy==='open-trade')income+=3;p.cash+=income;finishLanding(`${t.name} contributed A$${income}m in services and logistics.${p.owned.includes(p.pos)?' Your infrastructure generated the return.':''}`,{buy:!owner&&!p.owned.includes(p.pos),price:t.effect==='port'?30:24})}
function finishLanding(message,offer){render();if(offer&&offer.buy&&g.players[g.turn].cash>=offer.price){purchasePrompt(message,offer.price)}else{showLanding(message);}}
function showLanding(message){modal('Market briefing',`QUARTER ${String(g.round).padStart(2,'0')} / ROUTE UPDATE`,`<div class="event-stamp">${tiles[g.players[g.turn].pos].icon}</div><p class="event-detail">${message}</p><button class="primary-btn modal-primary" id="continue-turn">CONTINUE <span>↗</span></button>`);$('#continue-turn').onclick=()=>{$('#modal-root').classList.add('hidden');advance()}}
function purchasePrompt(message,price){modal('Build an asset','INVEST / OPTIONAL',`<p class="modal-copy">${message}</p><p class="event-detail">Acquire this tile's infrastructure rights for A$${price}m. It pays dividends and collects fees from rivals.</p><div class="turn-controls"><button class="secondary-btn" id="skip-buy">NOT NOW</button><button class="primary-btn" id="buy-asset">INVEST A$${price}m <span>↗</span></button></div>`);$('#skip-buy').onclick=()=>{showLanding(message)};$('#buy-asset').onclick=()=>{const p=g.players[g.turn];if(p.cash<price){toast('Insufficient funds.');return}p.cash-=price;p.owned.push(p.pos);addLog(p.name.toUpperCase(),`Invested A$${price}m in ${tiles[p.pos].name}.`);render();showLanding(`${message} Asset acquired for A$${price}m.`);sfx('cash')}}
